/* Badlands Field Map service worker (generated by tools/postbuild.mjs).
 * - App shell and landmark data (plain or encrypted): precached per version, served cache-first.
 * - Map tiles (plain or encrypted): served from the "bfm-tiles-v1" cache when downloaded,
 *   otherwise from the network.
 * - Photo-reading engine (ocr/) and the HEIC converter (vendor/): cached in "bfm-ocr-v1" on
 *   first use, then served from there.
 * - Personal records live in IndexedDB and are never touched here.
 */
const VERSION = '420d93013c5c';
const APP_CACHE = `bfm-app-${VERSION}`;
const TILE_CACHE = 'bfm-tiles-v1';
const OCR_CACHE = 'bfm-ocr-v1';
const PRECACHE = ["./","./assets/index-CAaChaJO.js","./assets/index-E78-S9Fx.css","./build.json","./data/enc/index.json.bfe","./data/enc/nasdara-game-tiers.png.bfe","./data/enc/nasdara-game.json.bfe","./data/index.json","./data/nasdara-core.json","./icons/apple-touch-icon.png","./icons/favicon-64.png","./icons/icon-192.png","./icons/icon-512.png","./icons/icon-maskable-512.png","./manifest.webmanifest"];
/** true: this version replaces a running one at once (the open page reloads itself). */
const TAKE_OVER = true;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(APP_CACHE);
      // Fetch each file fresh so a half-updated HTTP cache cannot mix versions.
      await Promise.all(
        PRECACHE.map(async (url) => {
          const res = await fetch(new Request(url, { cache: 'reload' }));
          if (!res.ok) throw new Error(`precache failed: ${url} ${res.status}`);
          await cache.put(url, res);
        }),
      );
      // The first install activates at once; later versions wait for the user (see SKIP_WAITING)
      // unless this version must replace the running one (TAKE_OVER).
      if (!self.registration.active || TAKE_OVER) await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key.startsWith('bfm-app-') && key !== APP_CACHE) await caches.delete(key);
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
  if (event.data && event.data.type === 'VERSION') event.source?.postMessage({ type: 'VERSION', version: VERSION });
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    event.respondWith(
      (async () => {
        const cache = await caches.open(APP_CACHE);
        return (await cache.match('./')) || (await cache.match('./index.html')) || fetch(req);
      })(),
    );
    return;
  }

  if (/\/data\/(enc\/)?tiles\//.test(url.pathname)) {
    event.respondWith(
      (async () => {
        const hit = (await caches.has(TILE_CACHE)) ? await (await caches.open(TILE_CACHE)).match(req.url) : undefined;
        if (hit) return hit;
        try {
          return await fetch(req);
        } catch {
          return new Response('', { status: 504, statusText: 'Tile not downloaded for offline use' });
        }
      })(),
    );
    return;
  }

  if (url.pathname.includes('/ocr/') || url.pathname.includes('/vendor/')) {
    event.respondWith(
      (async () => {
        const cache = await caches.open(OCR_CACHE);
        const hit = await cache.match(req.url, { ignoreSearch: true });
        if (hit) return hit;
        try {
          const res = await fetch(req);
          if (res.ok) await cache.put(req.url, res.clone());
          return res;
        } catch {
          return new Response('', { status: 504, statusText: 'Photo reading is not downloaded for offline use' });
        }
      })(),
    );
    return;
  }

  event.respondWith(
    (async () => {
      const cache = await caches.open(APP_CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      try {
        return await fetch(req);
      } catch {
        return new Response('', { status: 504, statusText: 'Offline' });
      }
    })(),
  );
});
